            const ctx = try self.peer.allocator.create(Mint.CallContext);
            var settled = false;
            ctx.* = .{ .user_ctx = user_ctx, .build = build, .callback = on_return, .settled_flag = &settled };
            const sent = if (self.origin == .exported)
                self.peer.sendCallResolvedGeneratedWithOptions(.{ .exported = .{ .id = self.cap_id } }, interface_id, Mint.ordinal, ctx, Mint.callBuild, Mint.callReturn, options)
            else
                self.peer.sendCallGeneratedWithOptions(self.cap_id, interface_id, Mint.ordinal, ctx, Mint.callBuild, Mint.callReturn, options);
            const question_id = sent catch |err| {
                if (!settled) self.peer.allocator.destroy(ctx);
                return err;
            };
            if (settled) return question_id;
            ctx.settled_flag = null;
            self.peer.setQuestionDeinitCtx(question_id, Mint.CallContext.deinitCtx);
            return question_id;
        }

